// Retrieve or initialize the buffer in the node's context to handle fragmentation
let state = context.get('serial_buffer') || Buffer.alloc(0);

// Buffer overflow prevention: Clear buffer if size exceeds 1024 bytes (noise protection)
const MAX_BUFFER_SIZE = 1024;
if (state.length > MAX_BUFFER_SIZE) {
    state = Buffer.alloc(0);
    node.warn("Serial buffer overflow threshold exceeded. Buffer cleared.");
}

// Append new chunk
if (msg.payload && Buffer.isBuffer(msg.payload)) {
    state = Buffer.concat([state, msg.payload]);
}

let outputs = [];
const REPORT_SIZE = 78;

while (state.length >= REPORT_SIZE) {
    let sync_found = false;
    for (let i = 0; i <= state.length - REPORT_SIZE; i++) {
        // Find Sync Bytes
        if (state[i] === 0xAA && state[i+1] === 0x55) {
            let frame = state.slice(i, i + REPORT_SIZE);

            // Calculate Checksum
            let calc_sum = 0;
            for (let j = 0; j < REPORT_SIZE - 2; j++) {
                calc_sum += frame[j];
            }
            calc_sum = calc_sum & 0xFFFF;
            let recv_sum = frame.readUInt16LE(REPORT_SIZE - 2);

            if (calc_sum === recv_sum) {
                let protocol = frame.readUInt8(3);
                let report_type = frame.readUInt8(4);
                let src_addr = frame.readUInt16LE(5);
                let rssi = frame.readInt8(7);
                let timestamp = frame.readUInt32LE(8);
                let payload_raw = frame.slice(12, 12 + 64);

                // --- UPDATE SHARED ROUTING MAP ---
                let activeNodesMap = flow.get('active_nodes_map') || {};
                activeNodesMap[src_addr] = protocol;
                flow.set('active_nodes_map', activeNodesMap);

                let proto_str = { 0: "ESP-NOW", 1: "Zigbee", 2: "LoRa" }[protocol] || "UNK";

                let outMsg = {
                    topic: "gateway/report",
                    protocol: proto_str,
                    src_addr_hex: "0x" + src_addr.toString(16).toUpperCase().padStart(4, '0'),
                    src_addr: src_addr,
                    rssi: rssi,
                    timestamp: timestamp,
                    report_type: report_type
                };

                if (report_type === 1) { // REPORT_TYPE_SENSOR_DATA
                    let ieee = [];
                    for (let k = 0; k < 6; k++) {
                        ieee.push(payload_raw.readUInt8(k).toString(16).toUpperCase().padStart(2, '0'));
                    }
                    let ieee_str = ieee.join(':');

                    let batt = payload_raw.readUInt16LE(9);
                    let temp_raw = payload_raw.readUInt16LE(11);
                    let temp = (temp_raw / 10.0) - 273.15;
                    let sats = payload_raw.readUInt8(13);
                    let lat = payload_raw.readInt32LE(14) / 1000000.0;
                    let lon = payload_raw.readInt32LE(18) / 1000000.0;
                    let curr = payload_raw.readUInt16LE(22);
                    let ax = payload_raw.readUInt16LE(24);
                    let ay = payload_raw.readUInt16LE(26);
                    let az = payload_raw.readUInt16LE(28);

                    outMsg.payload = {
                        ieee_addr: ieee_str,
                        short_addr: "0x" + src_addr.toString(16).toUpperCase().padStart(4, '0'),
                        msg_type: "SENSOR_DATA",
                        batt_mv: batt,
                        temperature: parseFloat(temp.toFixed(2)),
                        gnss_sats: sats,
                        latitude: parseFloat(lat.toFixed(6)),
                        longitude: parseFloat(lon.toFixed(6)),
                        current_ua: curr,
                        accel: `${ax}/${ay}/${az}`,
                        accel_x: ax,
                        accel_y: ay,
                        accel_z: az
                    };
                    outputs.push(outMsg);
                } else if (report_type === 2) { // REPORT_TYPE_NODE_STATUS
                    outMsg.payload = {
                        short_addr: "0x" + src_addr.toString(16).toUpperCase().padStart(4, '0'),
                        msg_type: "NODE_STATUS",
                        status: "Alive"
                    };
                    outputs.push(outMsg);
                } else if (report_type === 3) { // REPORT_TYPE_LOG_MESSAGE
                    let log_str = payload_raw.toString('utf8').replace(/\0/g, '').trim();
                    outMsg.payload = {
                        short_addr: "0x" + src_addr.toString(16).toUpperCase().padStart(4, '0'),
                        msg_type: "LOG_MESSAGE",
                        message: log_str
                    };
                    outputs.push(outMsg);
                }

                state = state.slice(i + REPORT_SIZE);
                sync_found = true;
                break;
            } else {
                state = state.slice(i + 2);
                sync_found = true;
                break;
            }
        }
    }

    if (!sync_found) {
        state = state.slice(state.length - 1);
        break;
    }
}

context.set('serial_buffer', state);

if (outputs.length > 0) {
    return [outputs];
} else {
    return null;
}

// Initialize node tracking context
let nodes = context.get('active_nodes') || {};

// Handle incoming telemetry
if (msg.topic === "gateway/report" && msg.payload && msg.payload.msg_type === "SENSOR_DATA") {
    let addr = msg.payload.short_addr;
    let proto = msg.protocol;

    // Node transitioned back online
    if (!nodes[addr] || nodes[addr].status === "offline") {
        node.send([null, { 
            topic: "node/alert", 
            payload: { short_addr: addr, status: "online", protocol: proto, timestamp: new Date().toISOString() } 
        }]);
    }

    nodes[addr] = {
        last_seen: new Date().getTime(),
        status: "online",
        protocol: proto
    };
    context.set('active_nodes', nodes);
    return [msg, null]; // Output telemetry to Output 1
}

// Handle periodic check (Triggered by Inject Node every 30s)
if (msg.topic === "check_heartbeat") {
    let now = new Date().getTime();
    const TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes offline limit

    for (let addr in nodes) {
        if (nodes[addr].status === "online" && (now - nodes[addr].last_seen) > TIMEOUT_MS) {
            nodes[addr].status = "offline";

            // Trigger Offline Alert to Output 2
            node.send([null, { 
                topic: "node/alert", 
                payload: { short_addr: addr, status: "offline", protocol: nodes[addr].protocol, timestamp: new Date().toISOString() } 
            }]);
        }
    }
    context.set('active_nodes', nodes);
}

return null;

let now = new Date();
let dateStr = now.toISOString().slice(0, 10); // Format: YYYY-MM-DD
msg.filename = `/var/log/sensor_data_${dateStr}.csv`;
return msg;

let p = msg.payload || {};
if (p.latitude && p.longitude) {
    msg.payload = {
        name: p.short_addr,
        lat: p.latitude,
        lon: p.longitude,
        icon: msg.protocol === "Zigbee" ? "fa-cube" : (msg.protocol === "LoRa" ? "fa-wifi" : "fa-mobile"),
        iconColor: "white",
        color: msg.protocol === "Zigbee" ? "orange" : (msg.protocol === "LoRa" ? "blue" : "green"),
        layer: "Active Nodes",
        message: `RSSI: ${msg.rssi} dBm<br>Batt: ${p.batt_mv} mV<br>Temp: ${p.temperature} °C`
    };
    return msg;
}
return null;

let p = msg.payload || {};

// 1. Resolve Hex Address
let destShort = 0xFFFF;
if (p.dest_addr) {
    destShort = parseInt(p.dest_addr.replace(/^0x/i, ''), 16);
    if (isNaN(destShort)) destShort = 0xFFFF;
}

// 2. Map Command Type
let cmdType = 0x02; // Default to CHANGE_PROTOCOL
if (p.command_type === "Read Attributes") {
    cmdType = 0x01;
} else if (p.command_type === "Change Protocol") {
    cmdType = 0x02;
} else if (p.command_type === "Change Sleep Interval") {
    cmdType = 0x03;
} else if (p.command_type === "Trigger GNSS") {
    cmdType = 0x04;
}

// 3. Map Target Protocol Enum
let targetProto = 0; // PROTO_WIFI (ESP-NOW)
if (p.protocol === "Zigbee") {
    targetProto = 1;
} else if (p.protocol === "LoRa") {
    targetProto = 2;
}

// 4. Resolve Value 3 parameter
let value3 = 0;
if (cmdType === 0x02) {
    value3 = targetProto;
} else if (cmdType === 0x03) {
    value3 = parseInt(p.sleep_interval) || 5;
} else if (cmdType === 0x01) {
    value3 = 0;
}

// 5. Look up routing protocol
let activeNodesMap = flow.get('active_nodes_map') || {};
let routeProto = 0;

if (destShort === 0xFFFF) {
    routeProto = targetProto;
} else if (activeNodesMap[destShort] !== undefined) {
    routeProto = activeNodesMap[destShort];
} else {
    routeProto = targetProto;
}

// 6. Allocate 12-Byte Command Frame
let buf = Buffer.alloc(12);
buf.writeUInt8(0xAA, 0); // sync1
buf.writeUInt8(0x55, 1); // sync2
buf.writeUInt8(routeProto, 2);
buf.writeUInt8(cmdType, 3);
buf.writeUInt16LE(destShort, 4);
buf.writeUInt16LE(0, 6);
buf.writeUInt16LE(0, 8);
buf.writeUInt16LE(value3, 10);

msg.payload = buf;
return msg;
